begin;
select extensions.no_plan();
create temp table v12_ctx as select w.id w,w.owner_id u,c.id cls,c.school_id school,c.school_year_id sy,t.id ta,
 (select id from public.enrollments where class_id=c.id and deleted_at is null order by id limit 1) enr,
 (select id from public.evaluation_rules where workspace_id=w.id limit 1) rule,
 (select id from public.evaluation_categories where workspace_id=w.id and code='written') category
 from public.workspaces w join public.classes c on c.workspace_id=w.id join public.teaching_assignments t on t.class_id=c.id
 where w.owner_id='11111111-1111-4111-8111-111111111111' order by c.id,t.id limit 1;
alter table v12_ctx add column grid jsonb,add column plan jsonb,add column assessment uuid default gen_random_uuid(),add column operation uuid default gen_random_uuid(),add column result uuid,add column grade uuid;
update v12_ctx set grid=jsonb_build_object('schema',1,'title','V12 prova fittizia','maximum','10','precision',2,'competencies','[]'::jsonb,'sections',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'label','Sezione','maximum','10','exercises',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'label','Esercizio','maximum','10','criteria',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'label','Procedimento','maximum','10','levels','[]'::jsonb)))))));
update v12_ctx set grid=jsonb_set(jsonb_set(grid,'{competencies}','[{"id":"skill-test","label":"Competenza fittizia","maximum":"10","description":""}]'),'{sections,0,exercises,0,criteria,0,competency_id}','"skill-test"');
update v12_ctx set plan=jsonb_build_object('source_year_id',sy,'school_id',school,'close_on','2027-08-31','source_classes',jsonb_build_array(cls),'target_year',jsonb_build_object('id',gen_random_uuid(),'label','2090/2091 V12','starts_on','2090-09-01','ends_on','2091-08-31'),'classes',jsonb_build_array(jsonb_build_object('id',gen_random_uuid(),'name','V12 destinazione')));
update v12_ctx set plan=plan||jsonb_build_object('students',(select jsonb_agg(jsonb_build_object('enrollment_id',e.id,'version',e.version,'outcome',case when e.id=v12_ctx.enr then 'promoted' else 'pending' end,'destination_id',case when e.id=v12_ctx.enr then plan->'classes'->0->>'id' else null end,'register_number',case when e.id=v12_ctx.enr then 1 else null end)) from public.enrollments e where e.class_id=cls and e.ends_on is null and e.deleted_at is null),'copies','[]'::jsonb);
update v12_ctx set plan=jsonb_set(plan,'{copies}',jsonb_build_array(jsonb_build_object('source_id',(select class_subject_id from public.teaching_assignments where id=ta),'destination_id',plan->'classes'->0->>'id','teachers',jsonb_build_array(jsonb_build_object('id',u,'confirmed',true)))));
grant select,update on v12_ctx to authenticated;
select extensions.ok((select count(*)=count(register_number) from public.enrollments),'Backfilled register numbers');
select extensions.ok(not has_function_privilege('anon','public.apply_year_transition(uuid,uuid,jsonb)','EXECUTE'),'Anonymous cannot transition');
select extensions.ok(not has_table_privilege('authenticated','public.year_transitions','INSERT'),'Audit cannot be forged');
select extensions.ok(not has_table_privilege('anon','public.v_grid_competency_progress','SELECT'),'Anonymous grid view denied');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
set local role authenticated;
select extensions.ok(public.validate_grid_definition((select grid from v12_ctx)),'Valid grid');
select extensions.throws_ok($q$select public.grid_grade('NaN'::numeric,80,'{}')$q$,'23514',null,'Non-finite score rejected');
select extensions.throws_ok($q$update public.evaluation_rules set band_maximum='NaN',version=version+1 where id=(select rule from v12_ctx)$q$,'23514',null,'Non-finite rule values rejected');
select extensions.throws_ok($q$select public.validate_grid_definition(jsonb_set((select grid from v12_ctx),'{maximum}','"11"'))$q$,'23514',null,'Inconsistent total rejected');
select extensions.is(public.grid_grade(30,80,'{"minimum":0,"maximum":10,"rounding_step":0.1,"conversion_mode":"bands","band_maximum":80,"bands":[{"from":0,"grade":3},{"from":30,"grade":4},{"from":38,"grade":5}]}'::jsonb),4::numeric,'Band lower boundary inclusive');
select extensions.is(public.grid_grade(29.999,80,'{"minimum":0,"maximum":10,"rounding_step":0.1,"conversion_mode":"bands","band_maximum":80,"bands":[{"from":0,"grade":3},{"from":30,"grade":4}]}'::jsonb),3::numeric,'No decimal gap before boundary');
select extensions.ok((select (public.preview_year_transition(w,plan)->>'valid')::boolean from v12_ctx),'Year preview validates');
select extensions.throws_ok($q$select public.preview_year_transition(w,jsonb_set(plan,'{copies,0,teachers,0,confirmed}','false')) from v12_ctx$q$,'P0001',null,'Every copied teacher requires explicit confirmation');
select extensions.ok(not exists(select 1 from public.year_transitions),'Preview writes no audit');
select extensions.lives_ok($q$select public.create_grid_assessment(w,assessment,null,null,grid,ta,'V12 test','2026-10-23','written',rule,(select version from public.evaluation_rules where id=v12_ctx.rule)) from v12_ctx$q$,'Create grid from existing canonical objects');
select extensions.lives_ok($q$select public.create_grid_assessment(w,assessment,null,null,grid,ta,'V12 test','2026-10-23','written',rule,(select version from public.evaluation_rules where id=v12_ctx.rule)) from v12_ctx$q$,'Assessment retry idempotent');
select extensions.lives_ok($q$select public.create_grid_assessment(w,gen_random_uuid(),null,null,grid,ta,'V12 second','2026-10-23','written',rule,(select version from public.evaluation_rules where id=v12_ctx.rule)) from v12_ctx$q$,'Reusing model rekeys exercise UUIDs');
select extensions.is((select count(*)::integer from public.assessment_questions where assessment_id=(select assessment from v12_ctx)),2,'Section and exercise reuse hierarchical questions');
create temp table v12_template as with made as (insert into public.assessment_rubrics(workspace_id,created_by,name,grid_definition) select w,u,'Modello fittizio V12',grid from v12_ctx returning id,version) select * from made;
select extensions.lives_ok($q$select public.create_grid_assessment(w,gen_random_uuid(),(select id from v12_template),(select version from v12_template),grid,ta,'V12 da modello','2026-10-23','written',rule,(select version from public.evaluation_rules where id=v12_ctx.rule)) from v12_ctx$q$,'Template creates detached assessment snapshot');
select extensions.throws_ok($q$update public.assessment_rubrics set deleted_at=now(),version=version+1 where id=(select id from v12_template)$q$,'23514',null,'Used template cannot hide historical assessments');
update public.assessment_rubrics set archived_at=now(),version=version+1 where id=(select id from v12_template);
select extensions.ok(exists(select 1 from public.assessments where title='V12 da modello'),'Logical template archive preserves assessment visibility');
select extensions.throws_ok($q$select public.create_grid_assessment(w,gen_random_uuid(),(select id from v12_template),2,grid,ta,'Forbidden archived','2026-10-23','written',rule,(select version from public.evaluation_rules where id=v12_ctx.rule)) from v12_ctx$q$,'P0002',null,'Archived template cannot start a new assessment');
insert into public.assessment_results(workspace_id,created_by,assessment_id,teaching_assignment_id,class_id,enrollment_id) select w,u,assessment,ta,cls,enr from v12_ctx;
update v12_ctx set result=(select id from public.assessment_results where assessment_id=assessment);
insert into public.question_results(workspace_id,created_by,assessment_result_id,assessment_id,question_id,max_score_snapshot,score) select w,u,result,assessment,q.id,10,8 from v12_ctx join public.assessment_questions q on q.assessment_id=assessment and q.parent_question_id is not null;
select extensions.is((select score from public.question_results where assessment_result_id=(select result from v12_ctx)),8::numeric,'Rapid exercise uses canonical score');
select extensions.ok((select obtained is null and missing_detail_count=1 from public.v_grid_competency_progress where assessment_id=(select assessment from v12_ctx)),'Rapid score does not fabricate competency detail');
select extensions.throws_ok($q$update public.question_results set criterion_scores='{"invalid":8}',version=version+1 where assessment_result_id=(select result from v12_ctx)$q$,'23514',null,'Foreign criterion denied');
update public.question_results set criterion_scores=jsonb_build_object((select a.grid_snapshot->'sections'->0->'exercises'->0->'criteria'->0->>'id' from public.assessments a where a.id=(select assessment from v12_ctx)),7),score=9,version=version+1 where assessment_result_id=(select result from v12_ctx);
select extensions.is((select score from public.question_results where assessment_result_id=(select result from v12_ctx)),7::numeric,'Analytical sum overrides supplied total: one score source');
select extensions.ok((select obtained=7 and available_maximum=10 and missing_detail_count=0 from public.v_grid_competency_progress where assessment_id=(select assessment from v12_ctx)),'Competency view uses existing analytical score');
insert into public.grade_entries(workspace_id,created_by,enrollment_id,teaching_assignment_id,class_id,category_id,rule_id,graded_on,origin,assessment_result_id,status) select w,u,enr,ta,cls,category,rule,'2026-10-23','assessment',result,'draft' from v12_ctx;
update v12_ctx set grade=(select id from public.grade_entries where assessment_result_id=result);
select extensions.ok((select calculation_snapshot ? 'grid' from public.grade_entries where id=(select grade from v12_ctx)),'Grade stores immutable grid snapshot');
create temp table v12_proposal as select suggested_value from public.grade_entries where id=(select grade from v12_ctx);
select extensions.lives_ok($q$update public.evaluation_rules set maximum=12,version=version+1 where id=(select rule from v12_ctx)$q$,'General rule may evolve');
update public.grade_entries set version=version+1 where id=(select grade from v12_ctx);
select extensions.is((select suggested_value from public.grade_entries where id=(select grade from v12_ctx)),(select suggested_value from v12_proposal),'Existing assessment keeps frozen conversion');
update public.grade_entries set status='confirmed',confirmed_value=suggested_value,change_reason='Conferma fittizia V12',version=version+1 where id=(select grade from v12_ctx);
update public.question_results set criterion_scores=null,score=9,version=version+1 where assessment_result_id=(select result from v12_ctx);
select extensions.is((select confirmed_value from public.grade_entries where id=(select grade from v12_ctx)),(select suggested_value from v12_proposal),'Editing scores does not silently change confirmed grade');
select extensions.ok(exists(select 1 from public.grade_audit_log where grade_entry_id=(select grade from v12_ctx)),'Canonical audit records grid grade confirmation');
select extensions.throws_ok($q$update public.enrollments set register_number=0,version=version+1 where id=(select enr from v12_ctx)$q$,'23514',null,'Register must be positive');
select extensions.throws_ok($q$update public.enrollments set register_number=(select register_number from public.enrollments where class_id=(select cls from v12_ctx) and id<>(select enr from v12_ctx) limit 1),version=version+1 where id=(select enr from v12_ctx)$q$,'23505',null,'Duplicate class number rejected');
select extensions.throws_ok($q$update public.enrollments set starts_on='2027-01-01',version=version+1 where id=(select enr from v12_ctx)$q$,'23514',null,'Historical activities prevent invalid enrollment dates');
select extensions.throws_ok($q$select public.preview_year_transition(w,jsonb_set(plan,'{students,0,version}','999999')) from v12_ctx$q$,'PT409',null,'Stale year preview rejected');
select extensions.is((select count(*)::integer from public.year_transitions),0,'Failed previews leave no audit');
select extensions.throws_ok($q$update public.assessments set grid_snapshot='{}',version=version+1 where id=(select assessment from v12_ctx)$q$,'23514',null,'Saved structure immutable');
select extensions.lives_ok($q$select public.apply_year_transition(w,operation,plan) from v12_ctx$q$,'Atomic year transition applies');
select extensions.is((select count(*)::integer from public.year_transitions),1,'One transition audit');
select extensions.lives_ok($q$select public.apply_year_transition(w,operation,plan) from v12_ctx$q$,'Year transition retry idempotent');
select extensions.is((select count(*)::integer from public.enrollments where class_id=((select plan from v12_ctx)->'classes'->0->>'id')::uuid),1,'Retry does not duplicate enrollment');
select extensions.is((select count(*)::integer from public.teaching_assignments where class_id=((select plan from v12_ctx)->'classes'->0->>'id')::uuid),1,'Only explicitly confirmed teacher copied once');
select extensions.ok((select ends_on='2027-08-31' and outcome='promoted' from public.enrollments where id=(select enr from v12_ctx)),'Origin logically closed');
select extensions.ok(not exists(select 1 from public.enrollments where class_id=(select cls from v12_ctx) and id<>(select enr from v12_ctx) and ends_on is not null),'Pending students remain unchanged');
select extensions.ok(exists(select 1 from public.assessment_results where id=(select result from v12_ctx)),'Historical scores remain visible after closure');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select extensions.throws_ok($q$select public.preview_year_transition(w,plan) from v12_ctx$q$,'42501',null,'Other workspace denied');
select extensions.is((select count(*)::integer from public.year_transitions),0,'Other workspace cannot read audit');
select extensions.is((select count(*)::integer from public.v_grid_competency_progress),0,'Competency projection cannot cross workspaces');
reset role;
insert into public.workspace_members(workspace_id,user_id,role) select w,'22222222-2222-4222-8222-222222222222','teacher' from v12_ctx;
set local role authenticated;
select extensions.throws_ok($q$select public.preview_year_transition(w,plan) from v12_ctx$q$,'42501',null,'Teacher cannot transition even within workspace');
select extensions.throws_ok($q$select public.apply_year_transition(w,gen_random_uuid(),plan) from v12_ctx$q$,'42501',null,'Teacher cannot apply transition');
reset role;
update public.workspace_members set role='viewer' where workspace_id=(select w from v12_ctx) and user_id='22222222-2222-4222-8222-222222222222';
set local role authenticated;
select extensions.throws_ok($q$select public.create_grid_assessment(w,gen_random_uuid(),null,null,grid,ta,'Forbidden','2026-10-23','written',rule,1) from v12_ctx$q$,'42501',null,'Viewer cannot create grid assessment');
reset role;
select * from extensions.finish();
rollback;
